import { readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { LANGUAGES } from '@/i18n/config';
import { OG_IMAGE_SIZE } from '@/lib/seo';

// The brand assets are generated by scripts/generate-assets.mjs and committed. These checks
// catch a missing, resized or bloated file, and a favicon that drifted from the palette.
const PUBLIC_DIR = path.resolve(process.cwd(), 'public');
const PNG_SIGNATURE = '89504e470d0a1a0a';
const OG_MAX_BYTES = 300 * 1024;

function readPng(relativePath: string): { width: number; height: number; bytes: number } {
  const data = readFileSync(path.join(PUBLIC_DIR, relativePath));
  expect(data.subarray(0, 8).toString('hex'), `${relativePath} is a PNG`).toBe(PNG_SIGNATURE);
  return {
    // IHDR: width and height are the first two big-endian 32-bit integers after the chunk header.
    width: data.readUInt32BE(16),
    height: data.readUInt32BE(20),
    bytes: data.length,
  };
}

describe('Open Graph images', () => {
  for (const lang of LANGUAGES) {
    it(`og/${lang}.png is ${OG_IMAGE_SIZE.width}x${OG_IMAGE_SIZE.height} and under 300 KB`, () => {
      const png = readPng(`og/${lang}.png`);
      expect(png.width).toBe(OG_IMAGE_SIZE.width);
      expect(png.height).toBe(OG_IMAGE_SIZE.height);
      expect(png.bytes).toBeLessThan(OG_MAX_BYTES);
    });
  }
});

describe('app icons', () => {
  const icons: Array<[string, number]> = [
    ['apple-touch-icon.png', 180],
    ['icons/icon-192.png', 192],
    ['icons/icon-512.png', 512],
    ['icons/icon-maskable-512.png', 512],
  ];
  for (const [file, size] of icons) {
    it(`${file} is ${size}x${size}`, () => {
      const png = readPng(file);
      expect(png.width).toBe(size);
      expect(png.height).toBe(size);
    });
  }
});

describe('favicon.svg', () => {
  const svg = readFileSync(path.join(PUBLIC_DIR, 'favicon.svg'), 'utf8');

  it('uses the design primary and on-primary colors, not the old amber', () => {
    expect(svg).toContain('#a5ed6e');
    expect(svg).toContain('#111111');
    expect(svg.toLowerCase()).not.toContain('#f59e0b');
  });

  it('is a small file', () => {
    expect(statSync(path.join(PUBLIC_DIR, 'favicon.svg')).size).toBeLessThan(2048);
  });
});

describe('favicon.ico', () => {
  const ico = readFileSync(path.join(PUBLIC_DIR, 'favicon.ico'));

  it('is an icon file with the 16, 32 and 48 px images, each a PNG', () => {
    expect(ico.readUInt16LE(0)).toBe(0);
    expect(ico.readUInt16LE(2)).toBe(1);
    const count = ico.readUInt16LE(4);
    const sizes: number[] = [];
    for (let i = 0; i < count; i++) {
      const entry = 6 + 16 * i;
      sizes.push(ico[entry]);
      const offset = ico.readUInt32LE(entry + 12);
      expect(ico.subarray(offset, offset + 8).toString('hex')).toBe(PNG_SIGNATURE);
    }
    expect(sizes).toEqual([16, 32, 48]);
  });

  it('is a small file', () => {
    expect(ico.length).toBeLessThan(8 * 1024);
  });
});
